import { describe, expect, it } from "vitest";
import {
	parseExerciseHistoryOptions,
	parseExerciseId,
	parseMeasurementDate,
	parsePagination,
	parseSearchMaxPages,
	parseSearchQuery,
	parseWeeks,
	parseWorkoutEventsOptions,
	parseWorkoutId,
	UsageError,
	requireMutationConfirmation,
	type CliArgs,
} from "./arguments.js";

const args = (
	options: CliArgs["options"] = {},
	positionals: string[] = [],
): CliArgs => ({ positionals, options });
const invalid = (callback: () => unknown, message: string) => {
	expect(callback).toThrow(UsageError);
	expect(callback).toThrow(message);
};

describe("CLI argument validation", () => {
	it("coerces pagination and preserves defaults", () => {
		expect(parsePagination(args())).toEqual({ page: 1, pageSize: 5 });
		expect(parsePagination(args({ page: "1", "page-size": "10" }))).toEqual({
			page: 1,
			pageSize: 10,
		});
	});

	it("rejects invalid and out-of-range pagination", () => {
		for (const page of ["0", "-1", "1.5", "nope"])
			invalid(
				() => parsePagination(args({ page })),
				"--page must be a positive integer",
			);
		for (const pageSize of ["0", "-1", "1.5", "nope", "11"])
			invalid(
				() => parsePagination(args({ "page-size": pageSize })),
				"--page-size must be a positive integer no greater than 10",
			);
	});

	it("validates event timestamps and maps options once", () => {
		expect(parseWorkoutEventsOptions(args())).toEqual({
			page: 1,
			pageSize: 5,
			since: "1970-01-01T00:00:00Z",
		});
		expect(
			parseWorkoutEventsOptions(
				args({
					page: "2",
					"page-size": "10",
					since: "2024-01-01T00:00:00+01:00",
				}),
			),
		).toEqual({ page: 2, pageSize: 10, since: "2024-01-01T00:00:00+01:00" });
		invalid(
			() => parseWorkoutEventsOptions(args({ since: "not-a-date" })),
			"--since must be an ISO timestamp",
		);
	});

	it("maps and validates optional exercise history dates", () => {
		expect(parseExerciseHistoryOptions()).toEqual({});
		expect(
			parseExerciseHistoryOptions(
				args({ "start-date": "2024-01-01T00:00:00+01:00" }),
			),
		).toEqual({ start_date: "2024-01-01T00:00:00+01:00" });
		expect(
			parseExerciseHistoryOptions(
				args({
					"start-date": "2024-01-01T00:00:00Z",
					"end-date": "2024-02-01T00:00:00Z",
				}),
			),
		).toEqual({
			start_date: "2024-01-01T00:00:00Z",
			end_date: "2024-02-01T00:00:00Z",
		});
		invalid(
			() => parseExerciseHistoryOptions(args({ "start-date": "2024-01-01" })),
			"--start-date must be an ISO timestamp",
		);
	});

	it("validates safe resource IDs and search terms", () => {
		expect(parseWorkoutId(" workout-1 ")).toBe("workout-1");
		expect(parseExerciseId(" exercise-1 ")).toBe("exercise-1");
		for (const value of [undefined, "", "  ", "a/b", "a?b"])
			invalid(() => parseWorkoutId(value), "Workout ID");
		for (const value of [undefined, "", "  ", "a/b", "a?b"])
			invalid(() => parseSearchQuery(value), "Search query");
		expect(parseSearchQuery(" Bench Press ")).toBe("bench press");
		expect(parseSearchMaxPages(args())).toBe(10);
		expect(parseSearchMaxPages(args({ "max-pages": "25" }))).toBe(25);
		invalid(
			() => parseSearchMaxPages(args({ "max-pages": "101" })),
			"--max-pages must be a positive integer no greater than 100",
		);
	});

	it("accepts real calendar dates and rejects impossible dates", () => {
		expect(parseMeasurementDate("2024-02-29")).toBe("2024-02-29");
		invalid(
			() => parseMeasurementDate("2023-02-29"),
			"Measurement date must be an ISO date",
		);
		invalid(
			() => parseMeasurementDate("2024-02-30"),
			"Measurement date must be an ISO date",
		);
	});

	it("coerces positive integer summary weeks", () => {
		expect(parseWeeks(args())).toBe(1);
		expect(parseWeeks(args({ weeks: "10" }))).toBe(10);
		for (const weeks of [
			"0",
			"-1",
			"1.5",
			"nope",
			"999999999999999999999",
			"521",
		])
			invalid(
				() => parseWeeks(args({ weeks })),
				"--weeks must be a positive integer no greater than 520",
			);
	});
});

describe("mutation confirmation", () => {
	it("requires an explicit true --yes flag", () => {
		expect(() =>
			requireMutationConfirmation(args({ yes: true })),
		).not.toThrow();
		for (const yes of [undefined, false])
			expect(() =>
				requireMutationConfirmation(args(yes === undefined ? {} : { yes })),
			).toThrow("Mutation requires --yes");
	});
});

import { Effect } from "effect";
import { createHevyClient, type HevyClient } from "@hevy-mcp/hevy-client";

type RequestConfig = {
	readonly url?: string;
	readonly method?: string;
	readonly path?: RequestPath;
	readonly query?: RequestQuery;
	readonly body?: unknown;
	readonly signal?: AbortSignal;
	readonly hevyDeadline?: number;
	readonly hevyTimeoutMs?: number;
};

type RequestPath = {
	readonly workoutId?: string;
	readonly routineId?: string;
	readonly exerciseTemplateId?: string;
	readonly folderId?: string;
	readonly date?: string;
};

type RequestQuery = {
	readonly page?: number;
	readonly pageSize?: number;
	readonly since?: string;
	readonly start_date?: string;
	readonly end_date?: string;
};

type RequestOptions = {
	readonly signal?: AbortSignal;
	readonly deadline?: number;
	readonly timeoutMs?: number;
};

type RequestEffectResponse = {
	readonly data: unknown;
	readonly status: number;
	readonly statusText: string;
	readonly headers: Headers;
};

type RequestEffect = (
	config: RequestConfig,
) => Effect.Effect<RequestEffectResponse, unknown>;

/**
 * Keep CLI test doubles compatible with the operations package's private
 * request-Effect seam while retaining Promise-shaped method spies for the
 * command assertions.
 */
export function createEffectClient(methods: Partial<HevyClient>): HevyClient {
	const native = createHevyClient({
		apiKey: "test-key",
		maxGetRetries: 0,
	});
	const seam = Object.getOwnPropertySymbols(native).find((symbol) =>
		symbol.description?.includes("native-request-effect"),
	);
	if (seam === undefined) {
		throw new Error("Missing native request Effect seam in test client");
	}
	const client = Object.assign(
		Object.create(Object.getPrototypeOf(native)),
		native,
		methods,
	) as HevyClient;
	Object.defineProperty(client, seam, {
		configurable: false,
		enumerable: false,
		value: ((config: RequestConfig) =>
			Effect.tryPromise({
				try: async () => ({
					data: await dispatch(methods, config),
					status: 200,
					statusText: "OK",
					headers: new Headers(),
				}),
				catch: (error) => error,
			})) satisfies RequestEffect,
		writable: false,
	});
	return client;
}

async function dispatch(
	methods: Partial<HevyClient>,
	config: RequestConfig,
): Promise<unknown> {
	const options = requestOptions(config);
	switch (config.url) {
		case "/v1/workouts": {
			if (config.method === "POST") {
				const method = methods.createWorkout;
				if (method === undefined) return {};
				return options === undefined
					? method(config.body as never)
					: method(config.body as never, options);
			}
			const method = methods.getWorkouts;
			if (method === undefined) return {};
			return options === undefined
				? method(config.query)
				: method(config.query, options);
		}
		case "/v1/routines": {
			if (config.method === "POST") {
				const method = methods.createRoutine;
				if (method === undefined) return {};
				return options === undefined
					? method(config.body as never)
					: method(config.body as never, options);
			}
			const method = methods.getRoutines;
			if (method === undefined) return {};
			return config.query === undefined
				? options === undefined
					? method()
					: method(undefined, options)
				: options === undefined
					? method(config.query)
					: method(config.query, options);
		}
		case "/v1/workouts/{workoutId}": {
			const workoutId = config.path?.workoutId;
			if (workoutId === undefined) return {};
			if (config.method === "PUT") {
				const method = methods.updateWorkout;
				if (method === undefined) return {};
				return options === undefined
					? method(workoutId, config.body as never)
					: method(workoutId, config.body as never, options);
			}
			const method = methods.getWorkout;
			if (method === undefined) return {};
			return options === undefined
				? method(workoutId)
				: method(workoutId, options);
		}
		case "/v1/routines/{routineId}": {
			const routineId = config.path?.routineId;
			if (routineId === undefined) return {};
			if (config.method === "PUT") {
				const method = methods.updateRoutine;
				if (method === undefined) return {};
				return options === undefined
					? method(routineId, config.body as never)
					: method(routineId, config.body as never, options);
			}
			const method = methods.getRoutineById;
			if (method === undefined) return {};
			return options === undefined
				? method(routineId)
				: method(routineId, options);
		}
		case "/v1/workouts/events": {
			const method = methods.getWorkoutEvents;
			if (method === undefined) return {};
			return options === undefined
				? method(config.query)
				: method(config.query, options);
		}
		case "/v1/workouts/count": {
			const method = methods.getWorkoutCount;
			if (method === undefined) return {};
			return options === undefined ? method() : method(options);
		}
		case "/v1/exercise_templates": {
			if (config.method === "POST") {
				const method = methods.createExerciseTemplate;
				if (method === undefined) return {};
				return options === undefined
					? method(config.body as never)
					: method(config.body as never, options);
			}
			const method = methods.getExerciseTemplates;
			if (method === undefined) return {};
			return options === undefined
				? method(config.query)
				: method(config.query, options);
		}
		case "/v1/exercise_templates/{exerciseTemplateId}": {
			const method = methods.getExerciseTemplate;
			const exerciseTemplateId = config.path?.exerciseTemplateId;
			if (method === undefined || exerciseTemplateId === undefined) return {};
			return options === undefined
				? method(exerciseTemplateId)
				: method(exerciseTemplateId, options);
		}
		case "/v1/exercise_history/{exerciseTemplateId}": {
			const method = methods.getExerciseHistory;
			const exerciseTemplateId = config.path?.exerciseTemplateId;
			if (method === undefined || exerciseTemplateId === undefined) return {};
			return options === undefined
				? method(exerciseTemplateId, config.query)
				: method(exerciseTemplateId, config.query, options);
		}
		case "/v1/routine_folders": {
			if (config.method === "POST") {
				const method = methods.createRoutineFolder;
				if (method === undefined) return {};
				return options === undefined
					? method(config.body as never)
					: method(config.body as never, options);
			}
			const method = methods.getRoutineFolders;
			if (method === undefined) return {};
			return options === undefined
				? method(config.query)
				: method(config.query, options);
		}
		case "/v1/routine_folders/{folderId}": {
			const method = methods.getRoutineFolder;
			const folderId = config.path?.folderId;
			if (method === undefined || folderId === undefined) return {};
			return options === undefined
				? method(folderId)
				: method(folderId, options);
		}
		case "/v1/body_measurements": {
			if (config.method === "POST") {
				const method = methods.createBodyMeasurement;
				if (method === undefined) return {};
				return options === undefined
					? method(config.body as never)
					: method(config.body as never, options);
			}
			const method = methods.getBodyMeasurements;
			if (method === undefined) return {};
			return options === undefined
				? method(config.query)
				: method(config.query, options);
		}
		case "/v1/body_measurements/{date}": {
			const date = config.path?.date;
			if (date === undefined) return {};
			if (config.method === "PUT") {
				const method = methods.updateBodyMeasurement;
				if (method === undefined) return {};
				return options === undefined
					? method(date, config.body as never)
					: method(date, config.body as never, options);
			}
			const method = methods.getBodyMeasurement;
			if (method === undefined) return {};
			return options === undefined ? method(date) : method(date, options);
		}
		case "/v1/user/info": {
			const method = methods.getUserInfo;
			if (method === undefined) return {};
			const data =
				options === undefined ? await method() : await method(options);
			return { data };
		}
		default:
			return {};
	}
}

function requestOptions(config: RequestConfig): RequestOptions | undefined {
	if (
		config.signal === undefined &&
		config.hevyDeadline === undefined &&
		config.hevyTimeoutMs === undefined
	) {
		return undefined;
	}
	return {
		signal: config.signal,
		deadline: config.hevyDeadline,
		timeoutMs: config.hevyTimeoutMs,
	};
}

